import SwiftUI

/// The client's languages. Russian text is the key; English and Simplified Chinese come from the table below.
/// The installer script itself speaks only Russian and English: with Chinese chosen its messages are English.
enum Lang: String, CaseIterable, Identifiable {
    case ru, en, zh
    var id: String { rawValue }
    var title: String { switch self { case .ru: "Русский"; case .en: "English"; case .zh: "中文" } }
    /// the language passed to lumen-install.sh (--lang)
    var installer: String { self == .ru ? "ru" : "en" }

    static var current: Lang = {
        if let s = UserDefaults.standard.string(forKey: "lang"), let l = Lang(rawValue: s) { return l }
        let pref = Locale.preferredLanguages.first ?? "en"
        if pref.hasPrefix("ru") { return .ru }
        if pref.hasPrefix("zh") { return .zh }
        return .en
    }()
}

/// The text for the current language; `%@` in the key are filled with args in order.
func L(_ key: String, _ args: String...) -> String {
    var s = key
    if Lang.current != .ru, let t = Strings.table[key] { s = Lang.current == .en ? t.0 : t.1 }
    for a in args {
        guard let r = s.range(of: "%@") else { break }
        s.replaceSubrange(r, with: a)
    }
    return s
}

/// Like L, as Text with markdown (**bold**, `code`, [links](url)) parsed after the values are filled in.
func T(_ key: String, _ args: String...) -> Text {
    var s = key
    if Lang.current != .ru, let t = Strings.table[key] { s = Lang.current == .en ? t.0 : t.1 }
    for a in args {
        guard let r = s.range(of: "%@") else { break }
        s.replaceSubrange(r, with: a)
    }
    if let a = try? AttributedString(markdown: s, options: .init(interpretedSyntax: .inlineOnlyPreservingWhitespace)) { return Text(a) }
    return Text(verbatim: s)
}

